import { Elysia } from "elysia";

import { ApiError } from "./errors";
import { assertMutationOrigin } from "./http";
import { authorizationRoute } from "./authorization/routes";
import { applicationsRoute } from "./applications/routes";
import { bootstrapRoute } from "./bootstrap/routes";
import { invitationsRoute } from "./invitations/routes";
import { shuiPlugin } from "./plugin";
import { serviceAccountsRoute } from "./service-accounts/routes";
import { systemRolesRoute } from "./system-roles/routes";
import { teamsRoute } from "./teams/routes";
import { usersRoute } from "./users/routes";

export function createApiRoutes() {
  return new Elysia({ name: "shui-api-routes", normalize: false })
    .use(shuiPlugin)
    .error({ ApiError })
    .onBeforeHandle(({ request, set, environment }) => {
      if (["POST", "PUT", "PATCH", "DELETE"].includes(request.method)) {
        assertMutationOrigin(environment, request);
      }
      set.headers["cache-control"] = "no-store";
      set.headers.pragma = "no-cache";
    })
    .onError(({ code, error, set }) => {
      set.headers["cache-control"] = "no-store";
      set.headers.pragma = "no-cache";
      const statusCode =
        error instanceof ApiError ? error.statusCode : code === "VALIDATION" ? 400 : 500;
      set.status = statusCode;
      return {
        error: statusCode >= 500 ? "Request failed." : "The request could not be completed.",
      };
    })
    .use(authorizationRoute)
    .use(applicationsRoute)
    .use(bootstrapRoute)
    .use(invitationsRoute)
    .use(usersRoute)
    .use(systemRolesRoute)
    .use(teamsRoute)
    .use(serviceAccountsRoute);
}
import { Elysia, t } from "elysia";

import { PASSWORD_RESET_TIMING_FLOOR_MS, type AuthEnvironment, createAuth } from "./auth";
import { createApiRoutes } from "./modules";

export function createApiApp(environment: AuthEnvironment) {
  const auth = createAuth(environment);

  return new Elysia({ aot: false, prefix: "/api" })
    .onRequest(async ({ request }) => requireApiResource(request))
    .use(createApiRoutes())
    .get("/health", () => ({ service: "shui-api", status: "ok" as const }), {
      response: t.Object({
        service: t.String(),
        status: t.Literal("ok"),
      }),
    })
    .head("/health", () => new Response(null, { status: 204 }))
    .mount(async (request) => {
      const isPasswordReset =
        request.method === "POST" &&
        new URL(request.url).pathname.endsWith("/auth/request-password-reset");
      const startedAt = Date.now();
      const response = await auth.handler(request);
      if (isPasswordReset) {
        const remaining = PASSWORD_RESET_TIMING_FLOOR_MS - (Date.now() - startedAt);
        if (remaining > 0) await new Promise((resolve) => setTimeout(resolve, remaining));
      }
      return response;
    });
}

